A={(0,0),(0,1),(1,1),(1,2),(2,0),(2,1)}; B={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def variants(s):
 out=[]
 for k in range(4):
  t={(x,y) for x,y in s}
  for _ in range(k): t={(y,-x) for x,y in t}
  for refl in [False,True]:
   u={(x,-y if refl else y) for x,y in t}
   mi=min(x for x,y in u); mj=min(y for x,y in u); out.append(frozenset((x-mi,y-mj) for x,y in u))
 return out
print(any(b in variants(A) for b in variants(B)))
print(variants(A)[0],variants(B)[0])
